package ro.leo.visual;
import ro.leo.i18n.L;import android.content.*;import android.os.Bundle;import android.view.KeyEvent;import android.widget.*;
/** Resumable, optional keypad walkthrough. Never changes network choices itself. */
public final class SetupWizardActivity extends LeoActivity {
 private int step;
 private static final String[] TITLES=L.array(new String[]{"Limba Leo","Dată și oră","Wi-Fi","SIM-uri","Taste și scriere","Notificări","Aspect și temă","Modul interfeței","Tastatură Leo","Comenzile telefonului","Gata"});
 static int boundedStep(int value){return Math.max(0,Math.min(TITLES.length-1,value));}
 protected void onCreate(Bundle b){super.onCreate(b);step=boundedStep(b==null?getSharedPreferences("setup",0).getInt("step",0):b.getInt("step",0));}
 protected void onResume(){super.onResume();show();}
 protected void onSaveInstanceState(Bundle b){b.putInt("step",step);super.onSaveInstanceState(b);}
 protected void onPause(){getSharedPreferences("setup",0).edit().putInt("step",step).apply();super.onPause();}
 private void show(){step=boundedStep(step);getSharedPreferences("setup",0).edit().putInt("step",step).apply();String[] help={
 L.t("Alege Română sau English. Limba aplicațiilor Android se schimbă separat."),L.t("Verifică ora automată, fusul orar și formatul ceasului."),L.t("Alege rețeaua Wi-Fi și introdu parola din taste."),L.t("Alege separat SIM-ul pentru apeluri, SMS și date. Nu se inițiază probe."),L.t("Săgeți: navigare. OK: deschide. Soft stânga: opțiuni. Soft dreapta: înapoi / șterge.\n# schimbă abc/ABC/123/T9. * schimbă sugestia T9."),
 LeoNotificationService.active==null?L.t("Notificările nu sunt conectate. Deschide pagina și alege Reîncearcă."):L.t("Accesul Leo la notificări este conectat."),L.t("Alege culorile, fundalul și mărimea textului."),L.t("Simplu: șase aplicații și setări uzuale. Complet: toate categoriile. Poți schimba oricând modul."),L.t("Alege modul de scriere și pauza multi-tap."),L.t("Meniu scurt: meniu global. Meniu lung: aplicații recente, configurabil în Personalizare.\nHome: 1 căutare, 0 media; tastele 2–9 caută la apăsare scurtă. Apăsarea lungă păstrează scurtăturile."),summary(this)};
 begin(L.t("Configurare · ")+(step+1)+"/"+TITLES.length);ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(TITLES.length);progress.setProgress(step+1);root.addView(progress,new LinearLayout.LayoutParams(-1,dp(5)));ScrollView scroll=new ScrollView(this);scroll.addView(text(TITLES[step]+"\n\n"+help[step],17));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));left=new Runnable(){public void run(){open();}};back=new Runnable(){public void run(){if(step>0){step--;show();}else options(L.t("Închizi ghidul?"),new String[]{L.t("Continuă"),L.t("Închide pentru acum")},new Choice(){public void pick(int at){if(at==1)finish();}});}};footer(step==TITLES.length-1?L.t("Finalizează"):L.t("Configurează"),step==TITLES.length-1?L.t("Gata"):L.t("Următor"),L.t("Înapoi"));
 }
 static String summary(Context c){return L.t("Mod interfață")+": "+(ShellMode.simple(c)?L.t("Simplu"):L.t("Complet"))+"\n"+L.t("Notificări")+": "+(LeoNotificationService.active!=null?L.t("Conectat"):L.t("De verificat"))+"\n"+L.t("Preferințele de rețea și SIM au fost păstrate. Poți relua ghidul din Setări → Telefon.");}
 private void complete(){getSharedPreferences("setup",0).edit().putBoolean("complete",true).putInt("step",0).apply();finish();}
 private void open(){if(step==10){complete();return;}if(step==7){ShellMode.choose(this,new Runnable(){public void run(){show();}});return;}Class<?>[] pages={LanguageSettingsActivity.class,DateTimeSettingsActivity.class,ConnectivityActivity.class,MobileSettingsActivity.class,KeypadLockSettingsActivity.class,NotificationsActivity.class,PersonalizationActivity.class,null,InputSettingsActivity.class,HelpActivity.class};Intent i=new Intent(this,pages[step]);if(step==2)i.putExtra("kind","wifi");startActivity(i);}
 public boolean dispatchKeyEvent(KeyEvent e){if(KeypadDialog.current()==null&&(e.getKeyCode()==KeyEvent.KEYCODE_DPAD_CENTER||e.getKeyCode()==KeyEvent.KEYCODE_ENTER||e.getKeyCode()==KeyEvent.KEYCODE_DPAD_RIGHT||e.getKeyCode()==KeyEvent.KEYCODE_DPAD_LEFT)){if(e.getAction()==KeyEvent.ACTION_UP){if(e.getKeyCode()==KeyEvent.KEYCODE_DPAD_LEFT){step=boundedStep(step-1);show();}else if(step==10)complete();else{step++;show();}}return true;}return super.dispatchKeyEvent(e);}
}
